package in.kalaimarket;
import com.fasterxml.jackson.databind.*;import java.net.*;import java.net.http.*;import java.time.*;import java.util.*;
import org.springframework.stereotype.Component;import org.springframework.scheduling.annotation.Scheduled;
@Component public class PublicMarketData {
 private final ObjectMapper json;private final PublicSignalService service;private final WatchRepository watch;private final HttpClient http=HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(5)).followRedirects(HttpClient.Redirect.NEVER).build();
 private final Map<String,String> errors=new java.util.concurrent.ConcurrentHashMap<>();private final Map<String,List<PublicSnapshot.Bar>> history=new HashMap<>();private final Map<String,Long> historyAt=new HashMap<>();private List<PublicSnapshot.News> events=List.of();private long calendarAt=0;
 public PublicMarketData(ObjectMapper j,PublicSignalService s,WatchRepository w){json=j;service=s;watch=w;}
 @org.springframework.beans.factory.annotation.Autowired private SignalAuditRecorder audit;
 public Map<String,String> errors(){return Map.copyOf(errors);}
 private JsonNode get(String url)throws Exception{var r=http.send(HttpRequest.newBuilder(URI.create(url)).timeout(Duration.ofSeconds(8)).header("Accept","application/json").GET().build(),HttpResponse.BodyHandlers.ofString());if(r.statusCode()!=200)throw new IllegalArgumentException("Public feed HTTP "+r.statusCode());if(r.body().length()>2000000)throw new IllegalArgumentException("Public response too large");return json.readTree(r.body());}
 private List<PublicSnapshot.Bar> bars(String asset,String provider,String tf,long now)throws Exception{String key=asset+"|"+provider+"|"+tf;long ttl=tf.equals("5m")?60000:180000;if(history.containsKey(key)&&now-historyAt.get(key)<ttl)return history.get(key);String base=provider.equals("SPOT")?"https://api.binance.com/api/v3/klines":"https://fapi.binance.com/fapi/v1/klines";JsonNode rows=get(base+"?symbol="+asset+"&interval="+tf+"&limit=700");if(!rows.isArray()||rows.size()<60)throw new IllegalArgumentException("Public candle history unavailable");var out=new ArrayList<PublicSnapshot.Bar>();for(JsonNode row:rows)out.add(new PublicSnapshot.Bar(row.get(0).asLong(),row.get(1).asDouble(),row.get(2).asDouble(),row.get(3).asDouble(),row.get(4).asDouble(),row.get(5).asDouble()));history.put(key,List.copyOf(out));historyAt.put(key,now);return out;}
 private void calendar(long now){if(now-calendarAt<300000)return;try{JsonNode data=get("https://nfs.faireconomy.media/ff_calendar_thisweek.json");if(!data.isArray()||data.isEmpty())throw new IllegalArgumentException();List<PublicSnapshot.News> out=new ArrayList<>();boolean week=false;ZoneId zone=ZoneId.of("America/New_York");LocalDate today=Instant.ofEpochMilli(now).atZone(zone).toLocalDate(),start=today.minusDays(today.getDayOfWeek().getValue()%7);for(JsonNode row:data){long ts=OffsetDateTime.parse(row.path("date").asText()).toInstant().toEpochMilli();LocalDate day=Instant.ofEpochMilli(ts).atZone(zone).toLocalDate();if(!day.isBefore(start)&&day.isBefore(start.plusDays(7)))week=true;if(row.path("impact").asText().equalsIgnoreCase("High")&&Set.of("USD","All").contains(row.path("country").asText()))out.add(new PublicSnapshot.News(ts,row.path("title").asText("Event")));}if(!week)throw new IllegalArgumentException();events=List.copyOf(out);calendarAt=now;errors.remove("calendar");}catch(Exception e){errors.put("calendar","Public news calendar unavailable; no new auto entries without a fresh calendar");}}
 private List<PublicSnapshot.Bar> scaled(List<PublicSnapshot.Bar> in,double f){return in.stream().map(b->new PublicSnapshot.Bar(b.t(),b.o()*f,b.h()*f,b.l()*f,b.c()*f,b.v())).toList();}
 PublicSnapshot load(String symbol,long now)throws Exception{
  boolean btc=symbol.equals("BTCUSD");String exchangeSymbol=btc?"BTCUSDT":symbol.equals("XAUUSD")?"XAUUSDT":"XAGUSDT",provider=btc?"SPOT":"FUTURES",source=btc?"Binance BTC/USDT":"Binance "+exchangeSymbol+" perp rebased to spot";
  double price;long at;if(btc){JsonNode q=get("https://api.binance.com/api/v3/ticker/24hr?symbol=BTCUSDT");price=q.path("lastPrice").asDouble();at=q.path("closeTime").asLong();}else{JsonNode q=get("https://api.gold-api.com/price/"+(symbol.equals("XAUUSD")?"XAU":"XAG"));price=q.path("price").asDouble();at=OffsetDateTime.parse(q.path("updatedAt").asText()).toInstant().toEpochMilli();}
  List<PublicSnapshot.Bar> c15;try{c15=bars(exchangeSymbol,provider,"15m",now);}catch(Exception failed){if(!symbol.equals("XAUUSD")||failed.getMessage()!=null&&failed.getMessage().contains("451"))throw failed;exchangeSymbol="PAXGUSDT";provider="SPOT";source="Binance PAXG proxy rebased to spot";c15=bars(exchangeSymbol,provider,"15m",now);}
  var c5=bars(exchangeSymbol,provider,"5m",now);var h1=bars(exchangeSymbol,provider,"1h",now);var h4=bars(exchangeSymbol,provider,"4h",now);double factor=btc?1:price/c15.get(c15.size()-1).c();if(factor<.9||factor>1.1)throw new IllegalArgumentException("Spot/exchange basis outside supported range");return new PublicSnapshot(symbol,source,at,price,scaled(c5,factor),scaled(c15,factor),scaled(h1,factor),scaled(h4,factor),events,calendarAt,btc||PublicSignalService.metalsOpen(now),now);
 }
 @Scheduled(fixedDelay=8000,initialDelay=4000) public void refresh(){if(!service.enabled())return;long now=System.currentTimeMillis();calendar(now);for(var item:watch.findAll()){if(!Set.of("XAUUSD","XAGUSD","BTCUSD").contains(item.symbol))continue;try{service.ingest(load(item.symbol,System.currentTimeMillis()));if(errors.remove(item.symbol)!=null&&audit!=null)audit.sourceState(item.symbol,"PUBLIC_FEED_RECOVERED","Public market data recovered");}catch(Exception e){String message=e.getMessage();String safeMessage=message!=null&&message.startsWith("Public")?message:"Public market data unavailable; MT5 is not needed for signals";if(!safeMessage.equals(errors.get(item.symbol))){if(audit!=null)audit.sourceState(item.symbol,"PUBLIC_FEED_UNAVAILABLE",safeMessage);errors.put(item.symbol,safeMessage);}}}}
}
